class thread: public boost::thread {
private:
	thread_local_context_ptr context;

	static std::string make_thread_name(const std::string &given_name);
	static void thread_main(const boost::function<void ()> func, thread_local_context_ptr ctx);

public:
	explicit thread(const boost::function<void ()> func,
		const std::string &name = std::string(),
		unsigned int stack_size = 0)
		: boost::thread()
	{
		context = thread_local_context::make_shared_ptr();
		context->thread_name = make_thread_name(name);
		thread_info = make_thread_info(boost::bind(thread_main, func, context));

		unsigned long min_stack_size;
		bool stack_min_size_defined;
		bool round_stack_size;

		#ifdef PTHREAD_STACK_MIN
			min_stack_size = PTHREAD_STACK_MIN;
			stack_min_size_defined = true;
		#else
			min_stack_size = 128 * 1024;
			stack_min_size_defined = false;
		#endif
		if (stack_size != 0 && stack_size < min_stack_size) {
			stack_size = min_stack_size;
			round_stack_size = !stack_min_size_defined;
		} else {
			round_stack_size = true;
		}

		if (round_stack_size) {
			long page_size;
			#if defined(_SC_PAGESIZE)
				page_size = sysconf(_SC_PAGESIZE);
			#elif defined(_SC_PAGE_SIZE)
				page_size = sysconf(_SC_PAGE_SIZE);
			#elif defined(PAGESIZE)
				page_size = sysconf(PAGESIZE);
			#elif defined(PAGE_SIZE)
				page_size = sysconf(PAGE_SIZE);
			#else
				page_size = getpagesize();
			#endif
			if (stack_size % page_size != 0) {
				stack_size = stack_size - (stack_size % page_size) + page_size;
			}
		}

		attributes attrs;
		attrs.set_stack_size(stack_size);
		start_thread(attrs);
	}

	std::string name() const throw();
	std::string backtrace() const throw();
	static std::string all_backtraces() throw();
	static std::string current_backtrace() throw();
	void interrupt(bool interruptSyscalls = true);
	void interrupt_and_join(bool interruptSyscalls = true) {
		bool done = false;
		while (!done) {
			interrupt(interruptSyscalls);
			done = timed_join(boost::posix_time::millisec(10));
		}
	}
	bool interrupt_and_join(unsigned int timeout, bool interruptSyscalls = true) {
		bool joined = false, timed_out = false;
		boost::posix_time::ptime deadline =
			boost::posix_time::microsec_clock::local_time() +
			boost::posix_time::millisec(timeout);
		while (!joined && !timed_out) {
			interrupt(interruptSyscalls);
			joined = timed_join(boost::posix_time::millisec(10));
			timed_out = !joined && boost::posix_time::microsec_clock::local_time() > deadline;
		}
		return joined;
	}
	static void interrupt_and_join_multiple(oxt::thread **threads, unsigned int size,
		bool interruptSyscalls = true)
	{
		std::list<oxt::thread *> remaining_threads;
		std::list<oxt::thread *>::iterator it, current;
		oxt::thread *thread;
		unsigned int i;

		for (i = 0; i < size; i++) {
			remaining_threads.push_back(threads[i]);
		}

		while (!remaining_threads.empty()) {
			for (it = remaining_threads.begin(); it != remaining_threads.end(); it++) {
				thread = *it;
				thread->interrupt(interruptSyscalls);
			}
			for (it = remaining_threads.begin(); it != remaining_threads.end(); it++) {
				thread = *it;
				if (thread->timed_join(boost::posix_time::millisec(0))) {
					current = it;
					it--;
					remaining_threads.erase(current);
				}
			}
			if (!remaining_threads.empty()) {
				syscalls::usleep(10000);
			}
		}
	}
};

class dynamic_thread_group {
private:
	struct thread_handle;
	typedef boost::shared_ptr<thread_handle> thread_handle_ptr;

	struct thread_handle {
		std::list<thread_handle_ptr>::iterator iterator;
		thread *thr;
		bool removed_from_list;

		thread_handle() {
			thr = NULL;
			removed_from_list = false;
		}

		~thread_handle() {
			delete thr;
		}
	};

	mutable boost::mutex lock;
	std::list<thread_handle_ptr> thread_handles;
	unsigned int nthreads;

	struct thread_func_data {
		boost::function<void ()> entry_point;
		thread_handle *handle;
	};

	struct thread_func_data_guard {
		thread_func_data *data;

		thread_func_data_guard(thread_func_data *_data)
			: data(_data)
			{ }

		~thread_func_data_guard() {
			delete data;
		}

		void clear() {
			data = NULL;
		}
	};

	struct thread_cleanup {
		dynamic_thread_group *thread_group;
		thread_handle *handle;

		thread_cleanup(dynamic_thread_group *g, thread_handle *h) {
			thread_group = g;
			handle = h;
		}

		~thread_cleanup() {
			boost::this_thread::disable_interruption di;
			boost::this_thread::disable_syscall_interruption dsi;
			boost::lock_guard<boost::mutex> l(thread_group->lock);
			if (!handle->removed_from_list) {
				thread_group->thread_handles.erase(handle->iterator);
				thread_group->nthreads--;
			}
		}
	};

	void thread_main(thread_func_data *data) {
		thread_func_data_guard guard(data);
		thread_cleanup c(this, data->handle);
		data->entry_point();
		data->entry_point = boost::function<void ()>();
	}

public:
	dynamic_thread_group() {
		nthreads = 0;
	}

	~dynamic_thread_group() {
		interrupt_and_join_all();
	}

	void create_thread(const boost::function<void ()> &func, const std::string &name = "", unsigned int stack_size = 0) {
		boost::lock_guard<boost::mutex> l(lock);
		thread_handle_ptr handle(new thread_handle());
		thread_handles.push_back(handle);
		handle->iterator = thread_handles.end();
		handle->iterator--;
		try {
			thread_func_data *data = new thread_func_data();
			thread_func_data_guard guard(data);
			data->entry_point = func;
			data->handle = handle.get();
			handle->thr = new thread(
				boost::bind(&dynamic_thread_group::thread_main, this, data),
				name,
				stack_size
			);
			guard.clear();
			nthreads++;
		} catch (...) {
			thread_handles.erase(handle->iterator);
			throw;
		}
	}

	void interrupt_all() {
		boost::unique_lock<boost::mutex> l(lock);
		std::list<thread_handle_ptr>::iterator it;
		for (it = thread_handles.begin(); it != thread_handles.end(); it++) {
			(*it)->thr->interrupt();
		}
	}

	void interrupt_and_join_all(bool interruptSyscalls = true) {
		boost::unique_lock<boost::mutex> l(lock);
		std::list<thread_handle_ptr> thread_handles_copy;
		std::list<thread_handle_ptr>::iterator it;
		thread_handle_ptr handle;
		unsigned int nthreads_copy = nthreads;
		std::vector<thread *> threads;
		unsigned int i = 0;

		threads.resize(nthreads);
		thread_handles_copy = thread_handles;
		for (it = thread_handles.begin(); it != thread_handles.end(); it++, i++) {
			handle = *it;
			handle->removed_from_list = true;
			threads[i] = handle->thr;
		}
		thread_handles.clear();
		nthreads = 0;

		l.unlock();
		if (!threads.empty()) {
			thread::interrupt_and_join_multiple(&threads[0], nthreads_copy, interruptSyscalls);
		}
	}

	void join_all() {
		boost::unique_lock<boost::mutex> l(lock);
		std::list<thread_handle_ptr> thread_handles_copy;
		std::list<thread_handle_ptr>::iterator it;
		thread_handle_ptr handle;
		unsigned int nthreads_copy = nthreads;
		std::vector<thread *> threads;
		unsigned int i = 0;

		threads.resize(nthreads);
		thread_handles_copy = thread_handles;
		for (it = thread_handles.begin(); it != thread_handles.end(); it++, i++) {
			handle = *it;
			handle->removed_from_list = true;
			threads[i] = handle->thr;
		}
		thread_handles.clear();
		nthreads = 0;

		l.unlock();
		for (i = 0; i < nthreads_copy; i++) {
			threads[i]->join();
		}
	}

	unsigned int num_threads() const {
		boost::lock_guard<boost::mutex> l(lock);
		return nthreads;
	}
};

